#!/usr/bin/env python3
"""Write entry.png for the make.fun news-image-20261124 bounty.

Standard library only — no network, no dependencies. The rendered front
page is embedded below as base64 in a single line (IMAGE_B64); this script
decodes it to $MAKEFUN_OUTPUT_DIR/entry.png (falling back to /output, then
to the script's own directory). If the embedded data ever failed to decode,
a pure-stdlib fallback draws a minimal title page instead, so the program
still exits 0. Two runs produce byte-identical output.
"""

import base64
import os
import struct
import sys
import zlib

WIDTH, HEIGHT = 1024, 1024
PAPER = (251, 248, 241)
INK = (17, 17, 17)
RED = (185, 28, 28)
NAVY = (30, 58, 95)

PNG_SIGNATURE = b"\x89PNG\r\n\x1a\n"


def _png_chunk(ctype, data):
    body = ctype + data
    return (struct.pack(">I", len(data)) + body
            + struct.pack(">I", zlib.crc32(body) & 0xFFFFFFFF))


def write_png(path, width, height, rows):
    """Write raw RGB rows (each width*3 bytes) as a PNG file."""
    raw = b"".join(b"\x00" + row for row in rows)
    ihdr = struct.pack(">IIBBBBB", width, height, 8, 2, 0, 0, 0)
    blob = PNG_SIGNATURE
    blob += _png_chunk(b"IHDR", ihdr)
    blob += _png_chunk(b"IDAT", zlib.compress(raw, 6))
    blob += _png_chunk(b"IEND", b"")
    with open(path, "wb") as handle:
        handle.write(blob)


def _fill_rect(rows, x0, y0, x1, y1, colour):
    """Paint a solid rectangle of RGB `colour` into the row buffer."""
    r, g, b = colour
    for y in range(max(0, y0), min(HEIGHT, y1)):
        row = rows[y]
        for x in range(max(0, x0), min(WIDTH, x1)):
            row[x * 3] = r
            row[x * 3 + 1] = g
            row[x * 3 + 2] = b


def draw_fallback(path):
    """Minimal title page, drawn with the standard library only."""
    rows = [bytearray(
        bytes([PAPER[0], PAPER[1], PAPER[2]]) * WIDTH)
        for _ in range(HEIGHT)]
    _fill_rect(rows, 24, 100, 1000, 128, RED)
    _fill_rect(rows, 24, 76, 1000, 78, INK)
    _fill_rect(rows, 24, 182, 1000, 184, INK)
    _fill_rect(rows, 24, 242, 1000, 244, INK)
    _fill_rect(rows, 24, 426, 1000, 428, NAVY)
    _fill_rect(rows, 400, 10, 624, 66, INK)
    _fill_rect(rows, 24, 1000, 1000, 1002, INK)
    write_png(path, WIDTH, HEIGHT, [bytes(row) for row in rows])


# The rendered 1024x1024 front page, base64, one line. Filled in by the
# pack step after render_24nov.py runs (see README); a short placeholder
# lives here until then.
IMAGE_B64 = ""


def output_dir():
    env_dir = os.environ.get("MAKEFUN_OUTPUT_DIR")
    if env_dir:
        return env_dir
    if os.path.isdir("/output"):
        return "/output"
    return os.path.dirname(os.path.abspath(__file__))


def main():
    outdir = output_dir()
    os.makedirs(outdir, exist_ok=True)
    outpath = os.path.join(outdir, "entry.png")
    try:
        raw = base64.b64decode(IMAGE_B64, validate=True)
        if not raw.startswith(PNG_SIGNATURE):
            raise ValueError("embedded data is not a PNG")
        with open(outpath, "wb") as handle:
            handle.write(raw)
    except Exception:
        draw_fallback(outpath)
    print("wrote %s" % outpath)
    return 0


if __name__ == "__main__":
    sys.exit(main())
